                consumed = offset
                scanned = 0
                while scanned < _RESPONSE_LOG_SCAN_BYTES:
                    chunk = stream.read(min(
                        _RESPONSE_LOG_CHUNK_BYTES,
                        _RESPONSE_LOG_SCAN_BYTES - scanned))
                    if not chunk:
                        break
                    scanned += len(chunk)
                    pending += chunk
                    while True:
                        newline = pending.find(b"\n")
                        if newline < 0:
                            break
                        line = pending[:newline]
                        pending = pending[newline + 1:]
                        consumed += newline + 1
